create table public.properties_v2 (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, owner_id uuid not null references public.owners(id) on delete restrict, name text not null, address_line text not null, city text, postal_code text, country_code text not null default 'ES', status public.property_status not null default 'onboarding', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz); alter table public.properties_v2 enable row level security;
